     "summary": "宁夏发改委发布《新型经营主体参与市场交易方案（征求意见稿）》，明确分布式光伏、风电及额定功率≤5兆瓦的10千伏以下储能项目为新型经营主体。其可选择直接交易、聚合交易或作为价格接受者参与市场；分布式储能参与辅助服务需满足充放电时长要求。计量结算按注册方式分类执行，均价按项目类型月度发布，储能暂按独立储能执行电价政策。",
