     "time": "10-20 23:00",
     "ts": 1792508420,
     "summary": "2026年前三季度，中国储能企业新增签约订单189个、容量1174.064GWh，创历史同期新高。订单呈现三大趋势：格局分化——电芯（69.4%）与系统（24.75%）合计占94.15%，资源向头部集中；出海主导——亚洲占超五成，北美门槛高、订单集中，欧洲合规趋严；技术多元——钠离子、液流、半固态等新型电池获GW级订单，多路线匹配差异化场景。",
